INSERT INTO public.kabupaten (code, name, type, capital, province_code, province, country, city, lat, lng, area_km2, population_2024, population_density, gdrp_per_capita_juta, tier, hdmi_2024, tourist_hotels, notes, source) VALUES
  ('5101', 'Jembrana', 'Kabupaten', 'Negara', '51', 'Bali', 'Indonesia', 'Negara', -8.3931, 114.6178, 847.515, 330221, 389, 47.2, '3', 0.741, 28, 'West Bali gate from Java via Gilimanuk port. Low tourism but strategic transit corridor.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5102', 'Tabanan', 'Kabupaten', 'Tabanan', '51', 'Bali', 'Indonesia', 'Tabanan', -8.3922, 115.0931, 848.539, 478393, 563, 61.4, '2', 0.7625, 195, 'Includes Tanah Lot, Jatiluwih rice terraces. Growing residential area west of Denpasar.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5103', 'Badung', 'Kabupaten', 'Mangupura', '51', 'Bali', 'Indonesia', 'Mangupura', -8.4847, 115.1764, 397.395, 537739, 1353, 138.7, '1', 0.8387, 1240, 'Richest regency in Bali. Includes Kuta, Seminyak, Canggu, Nusa Dua, Uluwatu. Tourism + retail hub.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5104', 'Gianyar', 'Kabupaten', 'Gianyar', '51', 'Bali', 'Indonesia', 'Gianyar', -8.5667, 115.3167, 363.782, 504845, 1387, 78.9, '2', 0.7736, 487, 'Includes Ubud, Sukawati art market. Cultural tourism hub with strong F&B scene.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5105', 'Klungkung', 'Kabupaten', 'Semarapura', '51', 'Bali', 'Indonesia', 'Semarapura', -8.5367, 115.4017, 312.115, 223723, 716, 52.1, '3', 0.7173, 87, 'Includes Nusa Penida island. Smallest mainland regency, growing tourism east of Gianyar.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5106', 'Bangli', 'Kabupaten', 'Bangli', '51', 'Bali', 'Indonesia', 'Bangli', -8.4611, 115.3461, 526.764, 260526, 494, 44.6, '3', 0.6936, 64, 'Only landlocked regency. Mount Batur & Kintamani highlands. Low retail density.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5107', 'Karangasem', 'Kabupaten', 'Amlapura', '51', 'Bali', 'Indonesia', 'Amlapura', -8.3683, 115.6014, 838.899, 538890, 642, 43.8, '3', 0.6735, 118, 'East Bali. Mount Agung, Tirta Gangga, Amed. Emerging dive tourism market.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5108', 'Buleleng', 'Kabupaten', 'Singaraja', '51', 'Bali', 'Indonesia', 'Singaraja', -8.1075, 115.085, 1322.124, 828156, 626, 49.7, '2', 0.7255, 215, 'Largest regency by area, north Bali. Singaraja is second largest city. Lovina beach, growing north tourism.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025'),
  ('5171', 'Denpasar', 'Kota', 'Denpasar', '51', 'Bali', 'Indonesia', 'Denpasar', -8.6705, 115.2126, 125.694, 673270, 5356, 95.3, '1', 0.8393, 312, 'Capital city of Bali. Largest population, business and government center, home to Living World Denpasar.', 'BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025')
