-- =============================================================
-- LocInsight — Supabase Migration 0007
-- Replace synthetic data with authoritative real data (BPS 2025 + OSM + Wikipedia)
-- Generated: 2026-08-09 09:14:11 UTC
-- 
-- This migration is IDEMPOTENT — safe to re-run without data loss.
-- Uses INSERT ... ON CONFLICT DO UPDATE (UPSERT) for all rows.
-- 
-- Sources:
--   - BPS Provinsi Bali 2025 (Badan Pusat Statistik) — Bali Dalam Angka 2025
--   - OSM Overpass API (admin_level=7) — 716 villages with KEMENDAGRI codes
--   - Wikipedia ID 'Daftar kecamatan dan kelurahan di Bali' (cross-check)
--   - map.co.id + mapactive.id (brand portfolios)
--   - OpenStreetMap (stores, competitors, POIs)
--   - nowbali.co.id + traveloka.com (malls)
-- 
-- Coverage:
--   - 1 country, 1 province, 9 kabupaten/kota
--   - 57 kecamatan, 716 villages (80 kelurahan + 636 desa)
--   - 94 brands, 20 malls, 136 stores
--   - 2708 POIs, 887 competitor stores
-- =============================================================

BEGIN;

-- 1. Add vill_type + osm_id + ref_kemendagri columns to kelurahan (idempotent)
ALTER TABLE public.kelurahan
  ADD COLUMN IF NOT EXISTS vill_type VARCHAR(10) DEFAULT 'kelurahan',
  ADD COLUMN IF NOT EXISTS osm_id BIGINT,
  ADD COLUMN IF NOT EXISTS ref_kemendagri VARCHAR(20);

-- 2. Countries
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, iso2 = EXCLUDED.iso2, iso3 = EXCLUDED.iso3;

-- 3. Provinces (Bali — BPS 2025 population)
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, country_id = EXCLUDED.country_id, country = EXCLUDED.country, lat = EXCLUDED.lat, lng = EXCLUDED.lng, area_km2 = EXCLUDED.area_km2, population = EXCLUDED.population;

-- 4. Kabupaten/Kota (9 — BPS 2025 stats)
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, capital = EXCLUDED.capital, province_code = EXCLUDED.province_code, province = EXCLUDED.province, country = EXCLUDED.country, city = EXCLUDED.city, lat = EXCLUDED.lat, lng = EXCLUDED.lng, area_km2 = EXCLUDED.area_km2, population_2024 = EXCLUDED.population_2024, population_density = EXCLUDED.population_density, gdrp_per_capita_juta = EXCLUDED.gdrp_per_capita_juta, tier = EXCLUDED.tier, hdmi_2024 = EXCLUDED.hdmi_2024, tourist_hotels = EXCLUDED.tourist_hotels, notes = EXCLUDED.notes, source = EXCLUDED.source;

-- 5. Kecamatan (57 — BPS 2024)
  ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, kabupaten_code = EXCLUDED.kabupaten_code, province = EXCLUDED.province, country = EXCLUDED.country, city = EXCLUDED.city, lat = EXCLUDED.lat, lng = EXCLUDED.lng, population_2024 = EXCLUDED.population_2024, area_km2 = EXCLUDED.area_km2, tier = EXCLUDED.tier, urban_score = EXCLUDED.urban_score, is_capital = EXCLUDED.is_capital, source = EXCLUDED.source;

-- 6. Villages (716 real — replace 161 synthetic)
-- TRUNCATE is safe: no FKs reference kelurahan table (verified in schema)
-- Real villages all carry ref_kemendagri (set by migration 0007)
-- Synthetic villages from migration 0005 had no ref_kemendagri
TRUNCATE TABLE public.kelurahan RESTART IDENTITY CASCADE;

  ON CONFLICT (id) DO UPDATE SET code = EXCLUDED.code, name = EXCLUDED.name, kec_code = EXCLUDED.kec_code, kec_name = EXCLUDED.kec_name, kab_code = EXCLUDED.kab_code, kab_name = EXCLUDED.kab_name, province = EXCLUDED.province, country = EXCLUDED.country, city = EXCLUDED.city, tier = EXCLUDED.tier, lat = EXCLUDED.lat, lng = EXCLUDED.lng, population = EXCLUDED.population, area_km2 = EXCLUDED.area_km2, density = EXCLUDED.density, urban_index = EXCLUDED.urban_index, income_index = EXCLUDED.income_index, tourist_index = EXCLUDED.tourist_index, transport_index = EXCLUDED.transport_index, poi_density_index = EXCLUDED.poi_density_index, is_coastal = EXCLUDED.is_coastal, vill_type = EXCLUDED.vill_type, osm_id = EXCLUDED.osm_id, ref_kemendagri = EXCLUDED.ref_kemendagri, source = EXCLUDED.source;

-- 7. Brands (94 MAP/MAA brands)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, parent = EXCLUDED.parent, category = EXCLUDED.category, origin_country = EXCLUDED.origin_country, format = EXCLUDED.format, location_preference = EXCLUDED.location_preference, typical_size_m2 = EXCLUDED.typical_size_m2, target_audience = EXCLUDED.target_audience, price_segment = EXCLUDED.price_segment, brand_strength = EXCLUDED.brand_strength, city = EXCLUDED.city, country = EXCLUDED.country, source = EXCLUDED.source, is_active = EXCLUDED.is_active;

-- 8. Malls (20 Bali malls)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, lat = EXCLUDED.lat, lng = EXCLUDED.lng, kec = EXCLUDED.kec, kab = EXCLUDED.kab, city = EXCLUDED.city, country = EXCLUDED.country, gla_m2 = EXCLUDED.gla_m2, opened_year = EXCLUDED.opened_year, class = EXCLUDED.class, anchor_count = EXCLUDED.anchor_count, has_cinema = EXCLUDED.has_cinema, has_supermarket = EXCLUDED.has_supermarket, has_department_store = EXCLUDED.has_department_store, visitor_estimate_daily = EXCLUDED.visitor_estimate_daily, notes = EXCLUDED.notes, source = EXCLUDED.source;

-- 9. Stores (136 MAP/MAA stores — unique outlet names)
  ON CONFLICT (id) DO UPDATE SET brand_id = EXCLUDED.brand_id, brand_name = EXCLUDED.brand_name, brand_category = EXCLUDED.brand_category, parent = EXCLUDED.parent, name = EXCLUDED.name, lat = EXCLUDED.lat, lng = EXCLUDED.lng, kec = EXCLUDED.kec, kab = EXCLUDED.kab, city = EXCLUDED.city, country = EXCLUDED.country, is_in_mall = EXCLUDED.is_in_mall, mall_id = EXCLUDED.mall_id, mall_name = EXCLUDED.mall_name, address = EXCLUDED.address, opened_year = EXCLUDED.opened_year, estimated_size_m2 = EXCLUDED.estimated_size_m2, confirmed = EXCLUDED.confirmed, source = EXCLUDED.source;

-- 10. POIs (2,708 Bali points of interest)
  ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, type = EXCLUDED.type, lat = EXCLUDED.lat, lng = EXCLUDED.lng, kec = EXCLUDED.kec, kab = EXCLUDED.kab, city = EXCLUDED.city, country = EXCLUDED.country, magnitude = EXCLUDED.magnitude, notes = EXCLUDED.notes, source = EXCLUDED.source;

-- 11. Competitor stores (887 — unique outlet names)
  ON CONFLICT (id) DO UPDATE SET brand_name = EXCLUDED.brand_name, brand_category = EXCLUDED.brand_category, name = EXCLUDED.name, lat = EXCLUDED.lat, lng = EXCLUDED.lng, kec = EXCLUDED.kec, kab = EXCLUDED.kab, city = EXCLUDED.city, country = EXCLUDED.country, address = EXCLUDED.address, is_in_mall = EXCLUDED.is_in_mall, mall_id = EXCLUDED.mall_id, mall_name = EXCLUDED.mall_name, source = EXCLUDED.source, source_url = EXCLUDED.source_url;

COMMIT;

